import{_ as n,l as s,o as t,c as l,v as e,p as i,x as o,d as p,i as A,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"FlashAttention-2 原文","description":"","frontmatter":{"title":"FlashAttention-2 原文","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dao-fa2.md","filePath":"llm/dao-fa2.md","lastUpdated":1789023840000}'),h={name:"llm/dao-fa2.md"};function F(c,a,E,m,f,u){const r=s("Mermaid");return t(),l("div",null,[a[1]||(a[1]=e('<h1 id="flashattention-2-原文" tabindex="-1">FlashAttention-2 原文 <a class="header-anchor" href="#flashattention-2-原文" aria-label="Permalink to &quot;FlashAttention-2 原文&quot;">​</a></h1><div class="epigraph"><p>第一代分块已不再写出二次矩阵，但线程块与 warp 之间的工作切分仍让占用率上不去；更快的精确注意力首先是更好的并行与划分。</p><footer>—— Dao，FlashAttention-2，2023（ICLR 2024）</footer></div><p>Tri Dao 单独署名的 <strong>FlashAttention-2</strong>（预印本 2023，ICLR 2024）把问题从「写不写得出 \\(A\\)」换成「同样的精确分块，如何吃满 GPU」。作者给出的观察：FA1 在 A100 上大约只到理论峰值的 <strong>25–40%</strong>，而精心写的 GEMM 可以高得多。算法对象不变：在线 softmax、SRAM 分块、反向可重算。改的是并行轴、warp 布局、非矩阵乘 FLOPs。划分细节见 <a href="/llm/flashattention-2">FlashAttention-2</a>。本篇写这篇短论文作为 <strong>占用率报告</strong>：测了什么形状、声称快多少、明确不覆盖解码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>FA1 的线程块主要沿 batch 和头数开。预训练为了塞长序列，batch 往往很小，GQA 再砍 KV 头，SM 数量大于「batch×头」这份并行度时，多处理器空转。块内 split-K：若干 warp 分切键，softmax 要跨 warp 归约，共享内存同步吃掉张量核时间。逐元素缩放若每步做满，总 FLOPs 里会有一截不走 MMA。三条低效彼此独立：只加大块填不满 SM；只改算术顺序去不掉 split-K 栅栏；只减 FLOPs 而不切查询维，长上下文仍然闲。</p><p>论文的读者已经接受「精确分块合法」。下一句必须是可复现的利用率数字，否则社区会继续把注意力当内存墙，而把算力墙误诊成「还要更多稀疏」。</p><h3 id="「2」不是新注意力" tabindex="-1">「2」不是新注意力 <a class="header-anchor" href="#「2」不是新注意力" aria-label="Permalink to &quot;「2」不是新注意力&quot;">​</a></h3><p>评测必须对齐：同一因果掩码、同一精度、同一是否 dropout。把 FA2 的加速解释成模型变了，会和近似注意力论文打架。ICLR 版本相对预印本主要是写清工作划分与实验，公式仍是 SDPA。</p><p><span class="marginnote">文献年份：arXiv:2307.08691，2023；会议 ICLR 2024。引用 <em>FlashAttention-2: Faster Attention with Better Parallelism and Work Partitioning</em>。不要叠造文号，也不要把 FA3 的 FP8 写进来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>并行：即使 \\(B=1\\)、头数有限，只要查询长度 \\(n\\) 够，就把查询行块分给不同线程块，铺满 SM。每块仍扫全部键值做在线 softmax，块间无需为输出归约。Warp：改为 split-Q，一行完整属于一个 warp，去掉 split-K 的片上归约。算法上推迟部分归一化，减少非 GEMM 逐元素运算。反向同样吃查询维并行。</p><p>作者在 A100 上报告相对 FA1 <strong>大约再快一倍</strong> 量级，峰值 FLOPs/s 提到大约 <strong>一半到七成</strong> 的理论值，并用 GPT 式端到端训练展示模型 FLOPs 利用率可以靠近同硬件上优化 GEMM 的舒适区。这些数字绑定头维、因果、是否 dropout、序列长度。短序列、已经很大的 batch 上，再切查询维的收益缩小。变长用 <code>cu_seqlens</code> 拼接；因果跳过整块；GQA 的并行度仍由查询头×查询行决定。</p>',12)),(t(),i(d,null,{default:o(()=>[A(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FA1%5B%22FA1%EF%BC%9Abatch%C3%97%E5%A4%B4%20%E5%BC%80%E5%9D%97%EF%BC%8C%E5%9D%97%E5%86%85%20split-K%22%5D%20--%3E%20BOT%5B%22%E5%8D%A0%E7%94%A8%E7%8E%87%2025%E2%80%9340%25%20%E9%87%8F%E7%BA%A7%22%5D%0A%20%20BOT%20--%3E%20Q%5B%22%E6%B2%BF%E6%9F%A5%E8%AF%A2%E8%A1%8C%E5%BC%80%E6%9B%B4%E5%A4%9A%E7%BA%BF%E7%A8%8B%E5%9D%97%22%5D%0A%20%20BOT%20--%3E%20W%5B%22warp%20%E6%94%B9%20split-Q%22%5D%0A%20%20BOT%20--%3E%20F%5B%22%E5%87%8F%E5%B0%91%E9%9D%9E%20GEMM%20FLOPs%22%5D%0A%20%20Q%20--%3E%20FA2%5B%22FA2%EF%BC%9A%E6%9B%B4%E6%8E%A5%E8%BF%91%20GEMM%20%E6%95%88%E7%8E%87%22%5D%0A%20%20W%20--%3E%20FA2%0A%20%20F%20--%3E%20FA2%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h3 id="训练图不是解码图" tabindex="-1">训练图不是解码图 <a class="header-anchor" href="#训练图不是解码图" aria-label="Permalink to &quot;训练图不是解码图&quot;">​</a></h3><p>论文主舞台是 \\(n_q\\approx n_k\\) 的训练与前填。解码 \\(n_q\\approx 1\\) 时查询维没有东西可切，占用率问题以另一种形式出现，需要沿键维切再 log-sum-exp 合并——那是 FlashDecoding，不是 FA2 正文。用 FA2 论文的 2× 去承诺聊天服务的 token/s，是错用实验设置。MLPerf 式 GPT 训练才是对口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>查询行之间没有 softmax 依赖，沿查询切并行在数学上免费。这与沿键切相反。Split-Q 改变数据复用形状：键值瓦片对块内 warp 广播，每 warp 私有累加自己的行。同步点减少后，寄存器更容易留给 MMA。非 GEMM FLOPs 削减让时间回到张量核主导——softmax 仍在，只是少做等价的重缩放。机制专文已写；原文作为论文还给出 <strong>可引用的利用率区间</strong>，使后续 FA3 能说「在 Hopper 上 FA2 又掉到三成多」而不显得无中生有。</p><p><span class="marginnote">若某硬件上共享内存极快、warp 归约很便宜，split-K 未必永远更差。FA2 的选择针对当时 A100 上测到的通信税。移植要重测。</span></p><h3 id="和-cudnn、和厂商融合核" tabindex="-1">和 cuDNN、和厂商融合核 <a class="header-anchor" href="#和-cudnn、和厂商融合核" aria-label="Permalink to &quot;和 cuDNN、和厂商融合核&quot;">​</a></h3><p>A100 时代厂商库也在追融合注意力。FA2 的贡献是开源算法说明：三条划分原则可复现。生产选型仍应在目标形状上实测，而不是「开源一定更快」。论文没有声称覆盖所有头维与所有掩码；不在支持列表就要回退。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><h3 id="安装了-2-x-包不等于走了最优核" tabindex="-1">安装了 2.x 包不等于走了最优核 <a class="header-anchor" href="#安装了-2-x-包不等于走了最优核" aria-label="Permalink to &quot;安装了 2.x 包不等于走了最优核&quot;">​</a></h3><p>框架有形状启发式与回退。自定义掩码、稀疏图案、奇数头维可能走 xformers 或物化。INT8/FP8 不是 FA2 的命题。占用率优化在 batch 已经很大时收益小。弱扩展（模型随卡数涨）与强扩展（固定模型加卡）的 MFU 故事不同，不要用训练曲线上的一点概括全部并行度。</p><p>ICLR 审稿关心的是：工作划分是否可迁移、数字是否只来自作者内核。读者应用同一组形状在公开 <code>flash-attn</code> 上复现量级，而不是逐百分比追论文图。因果与非因果、有无 dropout 要分列。</p><p>相对 FA1「大约再快一倍」是作者在 A100、长序列训练形状上的观察，不是对所有 \\((B,n,h,d)\\) 的常数。查询行不能被头数整除时出现尾块，占用率曲线会台阶状下跌。GQA 让 KV 头变少，FA1 的 batch×头并行更稀，FA2 沿查询切开的收益往往更大——这是架构变迁帮了工作划分，不是 FA2 改变了 GQA 的数学。端到端 GPT 训练的 MFU 还含 MLP、嵌入与通信；把「注意力核接近 GEMM 效率」写成「整网 MFU 等于 GEMM」会高估。反向重算仍在，步时与显存的交易没有取消，只是重算本身也更快了。</p><p>把 FA2 引进服务栈时，前填与解码要分核。前填走查询维并行；解码走 KV 维切分或厂商 decode 核。混合 batch 里既有长前填又有短 decode，调度器若只注册一个 FA2 核，短请求会被长循环拖死。这不是论文失败，是论文范围止于注意力算子。头维列表随 <code>flash-attn</code> 小版本增减，评测前应打印实际走的 kernel 名，避免把回退 GEMM 的延迟写成 FA2 的延迟。</p><p><span class="marginnote">出处：Dao，<em>FlashAttention-2</em>，ICLR 2024。解码见 FlashDecoding；Hopper 见 FA3。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FA2 保持精确分块，针对占用率、warp 通信与非 GEMM FLOPs。</li><li>A100 上相对 FA1 约再快一倍量级，利用率提到约 50–70% 峰值（随形状变）。</li><li>查询维并行救训练/前填，不救 \\(n_q=1\\) 的解码。</li><li>「2」不是新的 softmax 定义。</li><li>出处：Dao，ICLR 2024。</li></ul>',16))])}const M=n(h,[["render",F]]);export{B as __pageData,M as default};
